//! `sediment h`: byte-for-byte output against tests/fixtures/hash_cli
//! (generated by tests/gen/hash_cli.py from Python stdlib oracles), plus
//! argument parsing, warnings, limits and streaming boundaries.
use std::ffi::OsString;
use std::fs;
use std::io::Cursor;
use std::path::{Path, PathBuf};
use std::process::{Command, Output};
use std::sync::atomic::{AtomicU32, Ordering};

use sediment_engine::cli_hash::{
    format_report, hash_inputs, hash_reader, parse_hash_args, HashCliError, HashLimits, CHUNK,
};
use sediment_engine::hash_multi::{digest, HashMethod, ALL_METHODS};

const BIN: &str = env!("CARGO_BIN_EXE_sediment");
static N: AtomicU32 = AtomicU32::new(0);

fn fixtures() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/hash_cli")
}

fn expected(name: &str) -> String {
    fs::read_to_string(fixtures().join(name)).unwrap()
}

fn run_in(dir: &Path, args: &[&str]) -> Output {
    Command::new(BIN).arg("h").args(args).current_dir(dir).output().unwrap()
}

fn text(b: &[u8]) -> String {
    String::from_utf8_lossy(b).into_owned()
}

struct TempDir(PathBuf);
impl TempDir {
    fn new(tag: &str) -> TempDir {
        let p = std::env::temp_dir().join(format!(
            "sediment-hash-{tag}-{}-{}",
            std::process::id(),
            N.fetch_add(1, Ordering::Relaxed)
        ));
        let _ = fs::remove_dir_all(&p);
        fs::create_dir_all(&p).unwrap();
        TempDir(p)
    }
}
impl Drop for TempDir {
    fn drop(&mut self) {
        let _ = fs::remove_dir_all(&self.0);
    }
}

fn os(v: &[&str]) -> Vec<OsString> {
    v.iter().map(OsString::from).collect()
}

#[test]
fn default_crc32_tree_matches_oracle() {
    let out = run_in(&fixtures(), &["tree"]);
    assert_eq!(out.status.code(), Some(0), "{}", text(&out.stderr));
    assert_eq!(text(&out.stdout), expected("expected_default.txt"));
    assert!(out.stderr.is_empty());
}

#[test]
fn all_methods_tree_matches_oracle() {
    for spec in ["-scrc*", "-SCRC*"] {
        let out = run_in(&fixtures(), &[spec, "tree"]);
        assert_eq!(out.status.code(), Some(0), "{}", text(&out.stderr));
        assert_eq!(text(&out.stdout), expected("expected_all.txt"));
    }
    // Explicit full list in the same order is identical.
    let list = ALL_METHODS.iter().map(|m| m.name()).collect::<Vec<_>>().join(",");
    let out = run_in(&fixtures(), &[&format!("-scrc{list}"), "tree"]);
    assert_eq!(text(&out.stdout), expected("expected_all.txt"));
}

#[test]
fn single_file_and_method_order() {
    let out = run_in(&fixtures(), &["-scrcSHA256", "-scrccrc64", "tree/a.txt"]);
    assert_eq!(out.status.code(), Some(0));
    assert_eq!(text(&out.stdout), expected("expected_single.txt"));
    let out = run_in(&fixtures(), &["-scrcsha-256,CRC64", "--", "tree/a.txt"]);
    assert_eq!(text(&out.stdout), expected("expected_single.txt"));
}

#[test]
fn empty_file() {
    let out = run_in(&fixtures().join("tree"), &["-scrcMD5", "empty.bin"]);
    assert_eq!(out.status.code(), Some(0));
    assert_eq!(text(&out.stdout), expected("expected_empty.txt"));
    assert!(text(&out.stdout).contains("d41d8cd98f00b204e9800998ecf8427e"));
}

#[test]
fn missing_input_is_a_warning() {
    let out = run_in(&fixtures(), &["-scrcSHA256", "-scrcCRC64", "tree/a.txt", "no-such-file"]);
    assert_eq!(out.status.code(), Some(1));
    assert_eq!(text(&out.stdout), expected("expected_single.txt"));
    assert!(text(&out.stderr).contains("no-such-file"));
    // Nothing found at all: empty table with zero totals, still a warning.
    let out = run_in(&fixtures(), &["nothing-here"]);
    assert_eq!(out.status.code(), Some(1));
    let s = text(&out.stdout);
    assert!(s.contains("Files: 0\nSize: 0\n"), "{s}");
    assert!(s.contains("CRC32  for data:              00000000\n"), "{s}");
}

#[test]
fn usage_errors() {
    for args in [
        vec![],
        vec!["-scrc"],
        vec!["-scrcFOO", "x"],
        vec!["-scrcsha1,", "x"],
        vec!["-scrcsha1", "-scrcSHA1", "x"],
        vec!["-r", "x"],
        vec!["-scrcsha1"],
        vec!["--"],
    ] {
        let out = run_in(&fixtures(), &args);
        assert_eq!(out.status.code(), Some(2), "{args:?}");
        assert!(out.stdout.is_empty(), "{args:?}");
        assert!(text(&out.stderr).contains("usage"), "{args:?}");
    }
}

#[test]
fn double_dash_allows_dash_names_and_duplicates_are_listed() {
    let t = TempDir::new("dash");
    fs::write(t.0.join("-x"), b"abc").unwrap();
    let out = run_in(&t.0, &["-scrcmd5", "--", "-x", "-x"]);
    assert_eq!(out.status.code(), Some(0), "{}", text(&out.stderr));
    let s = text(&out.stdout);
    assert_eq!(s.matches("900150983cd24fb0d6963f7d28e17f72             3  -x\n").count(), 2, "{s}");
    assert!(s.contains("Files: 2\nSize: 6\n"));
    // Without `--` the name is an unknown switch.
    assert_eq!(run_in(&t.0, &["-x"]).status.code(), Some(2));
}

#[test]
fn names_are_escaped() {
    let t = TempDir::new("esc");
    fs::write(t.0.join("tab\there"), b"").unwrap();
    let out = run_in(&t.0, &["tab\there"]);
    assert_eq!(out.status.code(), Some(0));
    assert!(text(&out.stdout).contains("  tab\\there\n"));
}

#[cfg(unix)]
#[test]
fn unreadable_file_is_a_warning() {
    use std::os::unix::fs::PermissionsExt;
    let t = TempDir::new("perm");
    fs::write(t.0.join("ok"), b"abc").unwrap();
    let locked = t.0.join("locked");
    fs::write(&locked, b"secret").unwrap();
    fs::set_permissions(&locked, fs::Permissions::from_mode(0o000)).unwrap();
    if fs::read(&locked).is_ok() {
        return; // running as root; permissions are not enforced
    }
    let out = run_in(&t.0, &["ok", "locked"]);
    fs::set_permissions(&locked, fs::Permissions::from_mode(0o600)).unwrap();
    assert_eq!(out.status.code(), Some(1));
    let s = text(&out.stdout);
    assert!(s.contains("352441C2             3  ok\n"), "{s}");
    assert!(!s.contains("locked"));
    assert!(text(&out.stderr).contains("locked"));
}

#[cfg(unix)]
#[test]
fn symlink_loop_does_not_hang() {
    let t = TempDir::new("loop");
    fs::create_dir(t.0.join("d")).unwrap();
    fs::write(t.0.join("d/f"), b"abc").unwrap();
    std::os::unix::fs::symlink("..", t.0.join("d/up")).unwrap();
    let out = run_in(&t.0, &["d"]);
    assert!(matches!(out.status.code(), Some(0) | Some(1)));
    assert!(text(&out.stdout).contains("  d/f\n"));
}

#[test]
fn parse_args_library() {
    let a = parse_hash_args(&os(&["x"])).unwrap();
    assert_eq!(a.methods, vec![HashMethod::Crc32]);
    assert_eq!(a.inputs, vec![PathBuf::from("x")]);
    let a = parse_hash_args(&os(&["-scrcsha1", "a", "--", "-b", "--"])).unwrap();
    assert_eq!(a.methods, vec![HashMethod::Sha1]);
    assert_eq!(a.inputs, vec![PathBuf::from("a"), PathBuf::from("-b"), PathBuf::from("--")]);
    assert_eq!(parse_hash_args(&os(&[])), Err(HashCliError::Usage));
    assert_eq!(parse_hash_args(&os(&["-scrc*", "-scrcxx", "a"])), Err(HashCliError::Usage));
    // A lone "-" is a path (not a switch).
    assert_eq!(parse_hash_args(&os(&["-"])).unwrap().inputs, vec![PathBuf::from("-")]);
}

#[test]
fn hash_reader_streams_across_chunks() {
    let n = CHUNK * 2 + 17;
    let data: Vec<u8> = (0..n).map(|i| (i % 251) as u8).collect();
    let methods = [HashMethod::Crc32, HashMethod::Sha256, HashMethod::Blake2sp];
    let (size, ds) = hash_reader(&mut Cursor::new(&data), &methods, n as u64).unwrap();
    assert_eq!(size, n as u64);
    for (m, d) in methods.iter().zip(ds) {
        assert_eq!(d, digest(*m, &data));
    }
    let err = hash_reader(&mut Cursor::new(&data), &methods, n as u64 - 1).unwrap_err();
    assert_eq!(err.kind(), std::io::ErrorKind::InvalidData);
    let (size, _) = hash_reader(&mut Cursor::new(&[] as &[u8]), &methods, 0).unwrap();
    assert_eq!(size, 0);
}

#[test]
fn hash_inputs_limits() {
    let tree = fixtures().join("tree");
    let m = [HashMethod::Crc32];
    let rep = hash_inputs(std::slice::from_ref(&tree), &m, HashLimits::default()).unwrap();
    assert_eq!((rep.files, rep.folders, rep.total_size), (5, 3, 71049));
    assert_eq!(rep.rows.len(), 8);
    assert!(rep.warnings.is_empty());
    assert_eq!(format_report(&rep), expected("expected_default.txt"));
    let few = HashLimits { max_entries: 4, ..HashLimits::default() };
    assert_eq!(hash_inputs(std::slice::from_ref(&tree), &m, few), Err(HashCliError::LimitExceeded));
    let small = HashLimits { max_total_bytes: 71048, ..HashLimits::default() };
    assert_eq!(hash_inputs(std::slice::from_ref(&tree), &m, small), Err(HashCliError::LimitExceeded));
    let exact = HashLimits { max_total_bytes: 71049, ..HashLimits::default() };
    assert!(hash_inputs(std::slice::from_ref(&tree), &m, exact).is_ok());
    let shallow = HashLimits { max_depth: 1, ..HashLimits::default() };
    assert_eq!(hash_inputs(std::slice::from_ref(&tree), &m, shallow), Err(HashCliError::LimitExceeded));
    assert_eq!(hash_inputs(&[tree], &[], HashLimits::default()), Err(HashCliError::Usage));
    // Limits accumulate across inputs.
    let a = fixtures().join("tree/a.txt");
    let two = HashLimits { max_entries: 2, ..HashLimits::default() };
    assert!(hash_inputs(&[a.clone(), a.clone()], &m, two).is_ok());
    assert_eq!(hash_inputs(&[a.clone(), a.clone(), a], &m, two), Err(HashCliError::LimitExceeded));
}

#[test]
fn non_ascii_switch_is_usage_error_not_panic() {
    // Multi-byte characters straddling (or following) byte 5 must not panic.
    for sw in ["-scré", "-scrcé", "-sé", "-ééé", "-scr\u{1F600}", "-SCRC\u{1F600}", "-\u{1F600}scrc"] {
        assert_eq!(parse_hash_args(&os(&[sw, "x"])), Err(HashCliError::Usage), "{sw:?}");
    }
    // ASCII prefix is still case-insensitive.
    assert_eq!(parse_hash_args(&os(&["-SCRCsha1", "x"])).unwrap().methods, vec![HashMethod::Sha1]);
    let t = TempDir::new("nonascii");
    let out = run_in(&t.0, &["-scré", "x"]);
    assert_eq!(out.status.code(), Some(2), "stderr: {}", text(&out.stderr));
    assert!(text(&out.stderr).contains("usage"));
    assert!(out.stdout.is_empty());
}
